/// <summary>
/// When <c>WhsWorkExecuteDisplayProcessorOptimizedIsDetourButtonClickedFlight</c> is enabled, the system will try to determine if a detour button has been pressed (computationally cheaper) before invoking the SQL server to check if the session can support entering the detour (more expensive).
/// </summary>
internal final class WhsWorkExecuteDisplayProcessorOptimizedIsDetourButtonClickedFlight extends Flight
{
    static private WhsWorkExecuteDisplayProcessorOptimizedIsDetourButtonClickedFlight singleton = new WhsWorkExecuteDisplayProcessorOptimizedIsDetourButtonClickedFlight();
 
}
